def feature(s):
    props = s.get('element_properties', {})
    total = 0.0
    cubic = 0.0
    for element, fraction in s.get('composition', {}).items():
        r = props.get(element, {}).get('covalent_radius_A')
        if fraction is not None and fraction > 0 and r is not None and math.isfinite(r) and r > 0:
            total += fraction
            cubic += fraction * r ** 3
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0 or total <= 0 or cubic <= 0:
        return 0.0
    return float(math.log((4.0 * math.pi / 3.0) * cubic / (total * v)))

def feature(s):
    props = s.get('element_properties', {})
    total = 0.0
    electrons = 0.0
    for element, fraction in s.get('composition', {}).items():
        value = props.get(element, {}).get('valence_electrons')
        if fraction is not None and fraction > 0 and value is not None and math.isfinite(value):
            total += fraction
            electrons += fraction * value
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0 or total <= 0:
        return 0.0
    return float(electrons / (total * v))

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    neighbors = s.get('neighbors', [])
    for bond in neighbors:
        i = bond['i']
        j = bond['j']
        d = bond['distance_A']
        if d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    coordination = [0.0] * n
    for bond in neighbors:
        i = bond['i']
        j = bond['j']
        d = bond['distance_A']
        if d > 0 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[j]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    return float(sum(occ[i] * coordination[i] for i in range(n)) / weight)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    outer = [6.0] * n
    neighbors = s.get('neighbors', [])
    for bond in neighbors:
        i = bond['i']
        j = bond['j']
        d = bond['distance_A']
        if d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    for bond in neighbors:
        i = bond['i']
        j = bond['j']
        d = bond['distance_A']
        if occ[j] > 0 and d > 1.25 * nearest[i]:
            outer[i] = min(outer[i], d)
    weight = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    return float(sum(occ[i] * math.log(max(1.0, outer[i] / nearest[i])) for i in range(n) if math.isfinite(nearest[i])) / weight)
